const assert = require("node:assert/strict");
const { mkdirSync, writeFileSync, existsSync, readFileSync, renameSync } = require("node:fs");
const path = require("node:path");

module.exports = async ({ window, scratch, streams, requests, until, ui, evaluate, delayReply }) => {
  const output = path.resolve(__dirname, "../../docs/navigation-evidence"); mkdirSync(output, { recursive: true });
  const wc = window.webContents;
  wc.debugger.attach("1.3");
  const cdp = (method, params = {}) => wc.debugger.sendCommand(method, params);
  const run = async expression => {
    const result = await cdp("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
    if (result.exceptionDetails) throw new Error(result.exceptionDetails.exception?.description ?? result.exceptionDetails.text);
    return result.result.value;
  };
  const capture = async name => { const shot = await cdp("Page.captureScreenshot", { format: "png" }); writeFileSync(path.join(output, name + ".png"), Buffer.from(shot.data, "base64")); };
  const click = async selector => {
    await ui(`document.querySelector(${JSON.stringify(selector)})?.getBoundingClientRect().width > 0`);
    const point = await run(`(() => { const el = document.querySelector(${JSON.stringify(selector)}); if (!el) throw Error('Missing element'); el.scrollIntoView({block:'nearest'}); const r = el.getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);
    await cdp("Input.dispatchMouseEvent", { type: "mouseMoved", ...point });
    await cdp("Input.dispatchMouseEvent", { type: "mousePressed", button: "left", clickCount: 1, ...point });
    await cdp("Input.dispatchMouseEvent", { type: "mouseReleased", button: "left", clickCount: 1, ...point });
  };
  const row = id => `.session-item[data-session-id="${id}"]`;
  const menu = async (id, action) => {
    await ui(`document.querySelector(${JSON.stringify(row(id) + " .s-menu")})?.getBoundingClientRect().width > 0`);
    await click(row(id) + " .s-menu");
    await ui(`!!document.querySelector('.session-menu button[data-action="${action}"]')`);
    await click(`.session-menu button[data-action="${action}"]`);
  };
  window.setSize(1400, 900); window.showInactive();
  await run("applyPanelLayout(); setDrawer(true); refreshSessions()");
  await ui("navigationView.rows.size >= 2");
  assert.equal(await run('document.getElementById("drawer-close")'), null);
  const originalId = await run('selectedSessionId');
  await click("#session-new");
  await ui(`selectedSessionId !== ${JSON.stringify(originalId)} && workspaceReady.has(selectedSessionId)`);
  assert.equal(requests.length, 0, "whole-row creation does not submit a model request");
  const a = globalThis.__arcaneHosts.prep.activeHost;
  const aid = a.describeCurrent().id;
  await run('input.value = "production-A"; submit()');
  await ui('busy && messages.textContent.includes("A partial")');
  assert.equal((await run(`window.arcane.archiveSession(${JSON.stringify(aid)})`)).code, "SESSION_BUSY");
  assert.equal((await run(`window.arcane.deleteSession(${JSON.stringify(a.describeCurrent().path)}, modeContext())`)).code, "SESSION_NOT_ARCHIVED");
  await click(row(aid) + " .s-menu");
  await ui('!!document.querySelector(".session-menu")');
  assert.ok(await run('document.querySelector(".session-menu [data-action=archive]").disabled'));
  await run("navigationView.closeMenu()");
  await menu(aid, "pin");
  await ui(`!!document.querySelector('.nav-pinned ${row(aid)}')`);
  assert.equal(await run(`document.querySelectorAll(${JSON.stringify(row(aid))}).length`), 1);
  const first = path.join(scratch, "one", "adventure"), second = path.join(scratch, "two", "adventure");
  mkdirSync(first, { recursive: true }); mkdirSync(second, { recursive: true });
  const artifact = path.join(first, "existing.txt"); writeFileSync(artifact, "preserve project files");
  await run(`createProjectSession(${JSON.stringify(first)})`);
  const b = globalThis.__arcaneHosts.prep.activeHost, bid = b.describeCurrent().id;
  assert.equal(b.cwd(), first);
  await run('input.value = "production-B"; submit()');
  await ui('busy && messages.textContent.includes("B partial")');
  await run(`createProjectSession(${JSON.stringify(second)})`);
  const c = globalThis.__arcaneHosts.prep.activeHost, cid = c.describeCurrent().id;
  assert.equal(c.cwd(), second);
  await run("refreshSessions()");
  assert.equal(await run('[...navigationView.groups.keys()].filter(key => key.endsWith("adventure")).length'), 2);
  await capture("running-projects");
  await click("#session-search");
  await ui('!!document.querySelector(".session-search[open]")');
  await cdp("Input.insertText", { text: "production-A" });
  await ui('document.querySelectorAll(".search-result").length === 1');
  await capture("search");
  await cdp("Input.dispatchKeyEvent", { type: "keyDown", key: "Enter", code: "Enter", windowsVirtualKeyCode: 13 });
  await cdp("Input.dispatchKeyEvent", { type: "keyUp", key: "Enter", code: "Enter", windowsVirtualKeyCode: 13 });
  await ui(`selectedSessionId === ${JSON.stringify(aid)} && !document.querySelector(".session-search")`);
  await click(row(bid) + " .s-state");
  await ui(`selectedSessionId === ${JSON.stringify(bid)}`);
  await click("#session-search");
  await cdp("Input.insertText", { text: "no-match-acceptance-unique" });
  await ui('document.querySelectorAll(".search-result").length === 0');
  await cdp("Input.dispatchMouseEvent", { type: "mousePressed", button: "left", clickCount: 1, x: 10, y: 850 });
  await cdp("Input.dispatchMouseEvent", { type: "mouseReleased", button: "left", clickCount: 1, x: 10, y: 850 });
  await ui('!document.querySelector(".session-search")');
  // Cross-mode navigation is exercised through the visible row, never a prompt.
  const combat = globalThis.__arcaneHosts.combat.activeHost.describeCurrent().id;
  await click(row(combat) + " .s-body");
  await ui(`currentMode === "combat" && selectedSessionId === ${JSON.stringify(combat)}`);
  await click(row(bid) + " .s-body");
  await ui(`currentMode === "prep" && selectedSessionId === ${JSON.stringify(bid)} && messages.textContent.includes("B partial")`);
  await run('input.value = "B retained draft"; saveWorkspace(); globalThis.sidebarRows = [...document.querySelectorAll("#session-list .session-item")]');
  streams.get("A").finish(); streams.get("B").finish();
  await ui('!busy && messages.textContent.includes("B final result")');
  await until(() => !a.busy, "A completes independently");
  await ui(`document.querySelector('${row(aid)} .s-state').dataset.kind !== 'running'`);
  assert.ok(await run('sidebarRows.every((node,index)=>document.querySelectorAll("#session-list .session-item")[index]===node)'), "progress preserves row objects and order");
  const rightClickPoint = await run(`(() => {const r=document.querySelector('${row(bid)} .s-body').getBoundingClientRect(); return {x:r.x+10,y:r.y+10};})()`);
  await cdp("Input.dispatchMouseEvent", { type: "mousePressed", button: "right", clickCount: 1, ...rightClickPoint });
  await cdp("Input.dispatchMouseEvent", { type: "mouseReleased", button: "right", clickCount: 1, ...rightClickPoint });
  await ui('!!document.querySelector(".session-menu [data-action=rename]")');
  await capture("session-menu");
  await run('navigationView.closeMenu()');
  await menu(bid, "rename");
  await ui('!!document.querySelector("dialog[open] input")');
  await run('document.querySelector("dialog input").select()');
  await cdp("Input.insertText", { text: "Archived adventure" });
  await click("dialog button[type=submit]");
  await ui(`document.querySelector('${row(bid)} .s-title').textContent === "Archived adventure"`);
  await menu(bid, "archive");
  await ui(`!document.querySelector('#session-list ${row(bid)}') && selectedSessionId !== ${JSON.stringify(bid)}`);
  assert.ok(existsSync(b.describeCurrent().path)); assert.equal(readFileSync(artifact, "utf8"), "preserve project files");
  assert.equal(requests.length, 2);
  await click("#session-archives");
  await ui('!document.getElementById("archive-page").hidden');
  await capture("archives");
  await click(row(bid) + " .s-body");
  await ui(`selectedSessionId === ${JSON.stringify(bid)} && selectedArchived && messages.textContent.includes("B final result")`);
  assert.equal(await run("input.value"), "B retained draft");
  assert.ok(await run('getComputedStyle(composerWrap).display === "none"'));
  const before = requests.length;
  wc.reload(); await ui(`selectedSessionId === ${JSON.stringify(bid)} && selectedArchived && workspaceReady.has(selectedSessionId)`);
  assert.equal(requests.length, before); assert.equal(await run("input.value"), "B retained draft");
  await run("refreshSessions()");
  assert.ok(await run(`navigationView.rows.get(${JSON.stringify(aid)}).pinnedOrder != null`));
  await click("#archive-restore");
  await ui('!selectedArchived && getComputedStyle(composerWrap).display !== "none"');
  assert.equal(await run("input.value"), "B retained draft");
  assert.equal(await run(`navigationView.rows.get(${JSON.stringify(bid)}).pinnedOrder ?? null`), null);
  // Restored row is visible in its original project. A second archive can be undone.
  await menu(bid, "archive"); await ui(`navigationView.rows.get(${JSON.stringify(bid)}).archivedAt != null`);
  await click("#navigation-toast button"); await ui(`navigationView.rows.get(${JSON.stringify(bid)}).archivedAt == null`);
  await click(row(bid) + " .s-body");
  await ui(`selectedSessionId === ${JSON.stringify(bid)} && !selectedArchived`);
  const gate = { channel: "sessions:archive", sessionId: bid };
  delayReply(gate);
  await menu(bid, "archive");
  await until(() => gate.captured, "archive applied with its response held");
  await click("#session-archives");
  gate.release(); await until(() => gate.delivered, "archive acknowledgement released");
  await ui('!document.getElementById("navigation-toast").hidden');
  assert.ok(await run('!navigationView.archivePage.hidden'), "late archive completion must not undo a newer navigation");
  await menu(bid, "delete");
  await ui('!!document.querySelector("dialog[open]")');
  assert.ok(await run('document.querySelector("dialog").textContent.includes(t("navigation.deleteConfirm"))'));
  await click("dialog button[type=submit]");
  await ui(`!navigationView.rows.has(${JSON.stringify(bid)})`);
  assert.ok(!existsSync(b.describeCurrent().path)); assert.equal(readFileSync(artifact, "utf8"), "preserve project files");
  await click("#archive-back"); await click(row(aid) + " .s-body");
  await ui(`selectedSessionId === ${JSON.stringify(aid)} && messages.textContent.includes("A final result")`);
  assert.ok(await run('!document.getElementById("activity-toggle") && !document.getElementById("activity-list")'));
  for (const [name, width, height, panel] of [["wide", 1400, 900, 0], ["minimum", 720, 620, 0], ["split", 1400, 900, 944]]) {
    window.setSize(width, height);
    await run(`panelLayout.open=Boolean(${panel}); panelLayout.chatWidth=innerWidth-${panel}; applyPanelLayout(); setDrawer(${panel ? "true" : "false"}); true`).catch(() => {});
    await new Promise(resolve => setTimeout(resolve, 150));
    const shot = await cdp("Page.captureScreenshot", { format: "png" }); writeFileSync(path.join(output, name + ".png"), Buffer.from(shot.data, "base64"));
    assert.ok(await run('document.body.scrollWidth <= innerWidth'), name + " has no horizontal document overflow");
    if (panel) { await click("#drawer-backdrop"); await ui('!drawer.classList.contains("open")'); }
  }
  writeFileSync(path.join(output, "result.json"), JSON.stringify({ requests, passed: true, checks: ["CDP real pointer menus", "same-name distinct projects", "cross-mode navigation", "stable streaming rows", "busy archive rejected", "archived submit rejected", "rename", "archive history and draft", "reload", "restore", "undo", "confirmed permanent delete preserves files", "layout screenshots"] }, null, 2));
  await run(`openActivity(navigationView.rows.get(${JSON.stringify(cid)}))`);
  await ui(`selectedSessionId === ${JSON.stringify(cid)} && workspaceReady.has(selectedSessionId)`);
  await run('input.value = "Restart retained draft"; saveWorkspace()');
  await run(`window.arcane.renameSession(${JSON.stringify(cid)}, 'Restart archive')`);
  await run(`window.arcane.archiveSession(${JSON.stringify(cid)})`);
  const moved = second + "-temporarily-moved";
  for (const target of [second, moved]) assert.ok(path.resolve(target).startsWith(path.resolve(scratch) + path.sep));
  renameSync(second, moved);
  try {
    assert.equal((await run(`window.arcane.restoreSession(${JSON.stringify(cid)})`)).ok, true);
    const result = await run(`window.arcane.prompt('production-C', [], {...modeContext(), commandId:crypto.randomUUID()})`);
    assert.equal(result.code, "PROJECT_UNAVAILABLE");
    assert.equal(existsSync(second), false, "failed submission cannot silently recreate a missing project");
    assert.equal(requests.length, 2);
    assert.equal((await run(`window.arcane.archiveSession(${JSON.stringify(cid)})`)).ok, true);
  } finally { renameSync(moved, second); }
  const collapsed = await run(`navigationView.rows.get(${JSON.stringify(combat)}).projectKey`);
  await run(`navigationView.collapsed.add(${JSON.stringify(collapsed)}); navigationView.saveCollapse(); true`);
  writeFileSync(path.join(scratch, "sidebar-checkpoint.json"), JSON.stringify({ a: aid, c: cid, cwd: second, collapsed }));
  wc.debugger.detach();
};
